import "core-js/modules/es.array.push.js";
import { API, graphqlOperation } from "aws-amplify";
import { create_list_edit_delete_work_shift_timings } from "@/graphql/mutations.js";
import CreateShifts from "../PopUps/CreateShifts.vue";
import EditShifts from "../PopUps/EditShifts.vue";
import DeleteShifts from "../PopUps/DeleteShifts.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    CreateShifts,
    EditShifts,
    DeleteShifts,
    SnackBar
  },
  data() {
    return {
      status: "ACTIVE",
      statusItems: [{
        title: "Active",
        value: "ACTIVE"
      }, {
        title: "Deactive",
        value: "DEACTIVE"
      }],
      shiftHeaders: [{
        title: "Shift Name",
        value: "shift_name",
        align: "start"
      }, {
        title: "Start Time",
        value: "start_time"
      }, {
        title: "End Time",
        value: "end_time"
      }, {
        title: "Week-Offs",
        value: "week_off"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      tableData: [],
      tableLoading: false,
      // Pagination Handling
      currentPage: 1,
      itemsPerPage: 10,
      totalItems: 0,
      // Popups
      createShiftDialog: false,
      editShiftDialog: false,
      workshiftDeletion: false,
      workshiftData: {},
      SnackBarComponent: {},
      windowHeight: window.innerHeight - 250
    };
  },
  created() {
    this.get_shift_data();
  },
  computed: {
    paginatedShifts() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      for (let i = 1; i <= this.pageCount; i++) pages.push(i);
      return pages;
    }
  },
  watch: {
    tableData() {
      this.totalItems = this.tableData.length;
    }
  },
  methods: {
    Create_shifts() {
      this.createShiftDialog = true;
    },
    edit_workshift(item) {
      this.editShiftDialog = true;
      this.workshiftData = item;
    },
    delete_workshifts(item) {
      this.workshiftDeletion = true;
      this.workshiftData = item;
    },
    success_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
      this.createShiftDialog = false;
      this.editShiftDialog = false;
      this.workshiftDeletion = false;
      this.get_shift_data();
    },
    error_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
    },
    async get_shift_data() {
      this.tableLoading = true;
      try {
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_work_shift_timings, {
          input: {
            action_type: "LIST"
          }
        }));
        const response = JSON.parse(result.data.create_list_edit_delete_work_shift_timings);
        this.tableData = response.data || [];
        this.tableLoading = false;
      } catch (error) {
        this.tableLoading = false;
        const msg = error?.errors?.[0]?.message || error?.message || "Unable to load shift data";
        this.error_info(msg);
      }
    }
  }
};
